package com.yeyamo_mobile.api.commerce_service.messaging;
import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.commerce_service.application.*;import org.springframework.kafka.annotation.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.*;import java.util.*;
@Component public class PaymentEventConsumer{private final CommerceService service;private final ObjectMapper json;private final ProcessedPaymentEventRepository processed;public PaymentEventConsumer(CommerceService s,ObjectMapper j,ProcessedPaymentEventRepository p){service=s;json=j;processed=p;}@KafkaListener(topics="${yeyamo.kafka.topics.payment-events:payment.events}",groupId="${spring.kafka.consumer.group-id:commerce-service}")@Transactional public void consume(String raw)throws Exception{JsonNode root=json.readTree(raw);String id=root.path("eventId").asText();if(id.isBlank()||processed.existsById(id))return;if(root.path("eventVersion").asInt()!=1)throw new IllegalArgumentException("Unsupported event version");String type=root.path("eventType").asText();JsonNode p=root.path("payload");UUID order=UUID.fromString(p.path("bookingId").asText());if("payment.authorized".equals(type)||"payment.confirmed".equals(type))service.paid(order,p.path("paymentId").asText());else if("payment.refunded".equals(type))service.refundCompleted(order,UUID.fromString(root.path("correlationId").asText()),p.path("refundId").asText());else if("payment.failed".equals(type))service.paymentFailed(order);processed.save(new ProcessedPaymentEvent(id,type));}}
